async function contactFixture(){await exportFixture();const s=state();s.profile={claimNumber:'CLAIM-123',carrier:'Synthetic Carrier'};s.communications=[{id:'email1',transcript:'From: Taylor Adjuster <taylor@carrier.example>\nClaim CLAIM-123\nTaylor Lane\nClaims adjuster\n(916) 555-1234\nFormer contact: old@carrier.example'}];m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);return s;}
async function confirmContact(){assert.equal((await contactPost({action:'scan'})).status,200);const d=await(await contactGet()).json(),lead=d.contacts.find(c=>c.email==='taylor@carrier.example');assert.ok(lead);const r=await contactPost({action:'confirm',leadId:lead.id,name:'Taylor Lane',phone:'(916) 555-1234',note:'Checked assignment in current carrier email for CLAIM-123',sourceChecked:true,assignmentChecked:true});assert.equal(r.status,200,await r.clone().text());}
test('contact scan retains former and current email leads with source excerpts and requires assignment confirmation',async()=>{await contactFixture();assert.equal((await contactPost({action:'scan'})).status,200);let d=await(await contactGet()).json();assert.equal(d.contacts.filter(c=>['taylor@carrier.example','old@carrier.example'].includes(c.email)).length,2);assert.equal(d.active,null);assert.ok(d.contacts[0].sourceRef.startsWith('state:'));assert.ok(!JSON.stringify(d).includes('private-key'));assert.equal((await contactPost({action:'confirm',leadId:d.contacts[0].id,name:'Taylor Lane',phone:'',note:'Unchecked'})).status,400);await confirmContact();d=await(await contactGet()).json();assert.equal(d.active.current,true);assert.equal(d.active.email,'taylor@carrier.example');assert.equal(d.contacts.filter(c=>['taylor@carrier.example','old@carrier.example'].includes(c.email)).length,2);assert.equal(d.sendingConnected,false);});
test('confirmed contacts become stale after new correspondence or source metadata changes',async()=>{await contactFixture();await confirmContact();const s=state();s.communications.push({transcript:'New assignment: next@carrier.example'});m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);assert.equal((await(await contactGet()).json()).active.current,false);assert.equal((await contactPost({action:'draft',exportId:'missing',body:'Hello',reviewConfirmed:true})).status,400);});
test('inventory email contains exact reviewed PDF/XLSX bytes, mandatory claim subject and a truthful unsent status',async()=>{await contactFixture();await confirmContact();assert.equal((await invPost({action:'generate',note:'Reviewed synthetic contents package for email',reviewConfirmed:true})).status,200);const exported=state().contentsExportHistory[0];const r=await contactPost({action:'draft',exportId:exported.id,body:'Please review the attached inventory for CLAIM-123.',reviewConfirmed:true});assert.equal(r.status,200,await r.clone().text());let d=await(await contactGet()).json();assert.equal(d.drafts[0].status,'Prepared — not sent');assert.ok(d.drafts[0].subject.includes('CLAIM-123'));assert.equal(d.drafts[0].current,true);const response=await contactApi.GET(new Request('https://claims.test'+d.drafts[0].downloadUrl));assert.equal(response.status,200,await response.clone().text());const eml=await response.text();assert.match(eml,/X-Unsent: 1/);assert.match(eml,/To: taylor@carrier.example/);assert.match(eml,/application\/pdf/);assert.match(eml,/spreadsheetml.sheet/);assert.match(eml,/Content-Disposition: attachment/g);const bytes=new Uint8Array(await m.storage.get(exported.pdfKey).arrayBuffer());assert.ok(eml.includes(Buffer.from(bytes).toString('base64').match(/.{1,76}/g).join('\r\n')));assert.deepEqual(state().items,original.items);assert.deepEqual(state().buckets,original.buckets);m.sqlite.prepare("UPDATE claims SET name='Different insured' WHERE id=?").run(id);assert.equal((await contactApi.GET(new Request('https://claims.test'+d.drafts[0].downloadUrl))).status,409);});
test('tampered export attachment bytes and changed contact originals block draft download',async()=>{await contactFixture();await confirmContact();await invPost({action:'generate',note:'Test package',reviewConfirmed:true});const e=state().contentsExportHistory[0];await contactPost({action:'draft',exportId:e.id,body:'Inventory for review.',reviewConfirmed:true});const d=await(await contactGet()).json();await m.files().put(e.pdfKey,new TextEncoder().encode('%PDF-tampered'));assert.equal((await contactApi.GET(new Request('https://claims.test'+d.drafts[0].downloadUrl))).status,409);});
test('contact endpoint protects ownership, origin, versions and ordinary writes; AI activation is explicit',async()=>{await contactFixture();assert.equal((await contactPost({action:'scan',version:999})).status,409);assert.equal((await contactPost({action:'extract',fileIds:['source']})).status,503);assert.equal((await contactApi.POST(new Request('https://claims.test/api/adjuster-contact?id='+id,{method:'POST',headers:{origin:'https://evil.test'},body:'{}'}))).status,403);m.setUser({userId:'other',email:'other@example.test'});assert.equal((await contactGet()).status,404);m.setUser(null);assert.equal((await contactGet()).status,401);assert.match(authority.ordinaryWriteError({}, {adjusterContacts:{active:{email:'forged'}}}),/contact workflow/);assert.match(authority.ordinaryWriteError({}, {inventoryEmailDrafts:[{status:'Sent'}]}),/contact workflow/);});
test('text originals scan and manual document sources retain provenance and verify exact source bytes',async()=>{await contactFixture();const bytes=new TextEncoder().encode('Morgan Price\nClaim adjuster\nmorgan@carrier.example\nClaim CLAIM-123');m.sqlite.prepare('INSERT INTO evidence VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('transcript',id,companyModule.ADPA_OWNER,'Carrier email.txt','text/plain',bytes.length,'Email','','[]','transcript-key','2026-01-01');await m.files().put('transcript-key',bytes);assert.equal((await contactPost({action:'scan'})).status,200);let d=await(await contactGet()).json(),lead=d.contacts.find(c=>c.email==='morgan@carrier.example');assert.ok(lead);assert.equal(d.scan.textFiles,1);assert.ok(d.scan.skipped.some(f=>f.id==='source'));await m.files().put('transcript-key',new Uint8Array(bytes.length));assert.equal((await contactPost({action:'confirm',leadId:lead.id,name:'Morgan Price',phone:'',note:'Checked original',sourceChecked:true,assignmentChecked:true})).status,400);assert.equal((await contactPost({action:'manual',lead:{name:'Fake',email:'fake@carrier.example',phone:'',role:'',sourceRef:'file:foreign',locator:'Page 1',quote:'fake@carrier.example'},sourceChecked:true})).status,400);});
test('AI contact extraction validates supplied sources and quoted email, and treats output as leads',async()=>{const selected=[{id:'pdf1',filename:'Carrier.pdf',mime:'application/pdf',size:5}],read=async()=>new Uint8Array(5).buffer;let payload;const lead={name:'Taylor',email:'taylor@carrier.example',phone:'',role:'Adjuster',sourceRef:'file:pdf1',locator:'Page 1',quote:'Taylor: taylor@carrier.example'};const fetcher=async(_url,o)=>{payload=JSON.parse(o.body);return Response.json({status:'completed',output:[{content:[{type:'output_text',text:JSON.stringify({contacts:[lead]})}]}]});};const found=await contact.extractContactAI('test','test-model',selected,read,fetcher);assert.equal(found[0].method,'AI document lead');assert.equal(found[0].confirmed,undefined);assert.equal(payload.store,false);assert.ok(payload.instructions.includes('untrusted'));lead.sourceRef='file:foreign';await assert.rejects(contact.extractContactAI('test','test-model',selected,read,fetcher),/unsupported/);lead.sourceRef='file:pdf1';lead.quote='No email visible';await assert.rejects(contact.extractContactAI('test','test-model',selected,read,fetcher),/unsupported/);});
test('email generation rejects header injection, unsafe filenames and missing claim subject',()=>{const a=[{name:'ADPA-contents-one.pdf',type:'application/pdf',bytes:new Uint8Array(5)},{name:'ADPA-contents-one.xlsx',type:'application/x',bytes:new Uint8Array(5)}];assert.throws(()=>contact.inventoryEmail({to:'valid@carrier.example',subject:'Claim C123\r\nBcc: bad@evil.test',claimNumber:'C123',body:'Text'},a),/Invalid/);assert.throws(()=>contact.inventoryEmail({to:'valid@carrier.example',subject:'Inventory',claimNumber:'C123',body:'Text'},a),/Invalid/);});
test('uploaded .eml sources decode MIME headers and base64 body without scanning binary attachments or rendering HTML',async()=>{await contactFixture();const email='From: Morgan Price <morgan@carrier.example>\r\nTo: ADPA <staff@adpa.example>\r\nSubject: Claim CLAIM-123\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n'+Buffer.from('Claims adjuster\nDirect: replacement@carrier.example').toString('base64');const bytes=new TextEncoder().encode(email);m.sqlite.prepare('INSERT INTO evidence VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('email-original',id,companyModule.ADPA_OWNER,'Carrier.eml','message/rfc822',bytes.length,'Email','','[]','email-original-key','2026-01-01');await m.files().put('email-original-key',bytes);const r=await contactPost({action:'scan'});assert.equal(r.status,200,await r.clone().text());const d=await(await contactGet()).json();assert.ok(d.contacts.some(c=>c.email==='morgan@carrier.example'&&c.sourceRef==='file:email-original'));assert.ok(d.contacts.some(c=>c.email==='replacement@carrier.example'));const parsed=await contact.emailText(bytes.buffer);assert.ok(parsed.includes('Claims adjuster'));assert.ok(parsed.includes('Email attachments require separate'));});
