const reconGet=comp=>reconApi.GET(new Request('https://claims.test/api/inventory-reconciliation?id='+id+(comp?'&comparisonId='+comp:'')));
const reconPost=b=>reconApi.POST(new Request('https://claims.test/api/inventory-reconciliation?id='+id,{method:'POST',headers:{origin:'https://claims.test','Content-Type':'application/json'},body:JSON.stringify({version:latestVersion(),...b})}));
async function reconFixture(legacy=false){const sub=await reportedFixture(),s=state();if(legacy){delete s.contentsExportHistory[0].modelKey;delete s.contentsExportHistory[0].modelDigest;m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);}const r=await reconPost({action:'start',exportId:sub.exportId,submissionId:sub.id,title:'Synthetic carrier contents revision',claimChecked:true});assert.equal(r.status,200,await r.clone().text());return state().inventoryComparisons[0];}
const columns={description:0,room:1,tag:-1,quantity:2,unit:3,unitPrice:4,rcv:5,depreciation:6,acv:7};
async function addCarrier(comp,rcv='199.99'){const csv='Description,Room,Quantity,Unit,Unit price,RCV,Depreciation,ACV\r\nRefrigerator,Kitchen,1,EA,199.99,'+rcv+',50.00,'+(Number(rcv)-50).toFixed(2)+'\r\n';const bytes=new TextEncoder().encode(csv);m.sqlite.prepare('INSERT INTO evidence VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('carrier',id,companyModule.ADPA_OWNER,'Carrier.csv','text/csv',bytes.length,'Contents','','[]','carrier-key','2026-10-13');await m.files().put('carrier-key',bytes);const r=await reconPost({action:'import',comparisonId:comp.id,fileId:'carrier',sheet:'CSV',headerRow:1,firstRow:2,lastRow:2,columns,amountBasis:'Extended item totals USD',currencyChecked:true,claimChecked:true});assert.equal(r.status,200,await r.clone().text());return state().inventoryComparisons[0];}
const groupInput=(comp,patch={})=>({action:'group',comparisonId:comp.id,groupId:'',adpaRefs:['care:care1'],carrierIds:[comp.carrierRows[0]?.id].filter(Boolean),basis:'RCV',disposition:'Disputed',note:'Original item, quantity, extended USD replacement price and tax/shipping basis reviewed',sourceChecked:true,comparableBasisChecked:true,omissionSearchChecked:false,agreementFileId:'',agreementLocator:'',agreementQuote:'',...patch});
async function excludeLegacy(comp){const r=await reconPost(groupInput(comp,{adpaRefs:['item:0'],carrierIds:[],disposition:'Excluded',note:'Legacy requested amount is unpriced and excluded from this supported valuation comparison'}));assert.equal(r.status,200,await r.clone().text());}
test('reconciliation freezes the actual submitted baseline and does not promote legacy requested amounts to approved demand',async()=>{const comp=await reconFixture(),d=await(await reconGet(comp.id)).json();assert.equal(d.detail.baseline.rows.length,2);assert.equal(d.detail.baseline.rows[0].rcvCents,null);assert.equal(d.detail.baseline.rows[0].existingRequested,400);assert.equal(d.detail.baseline.rows[1].rcvCents,29999);assert.equal(d.detail.baseline.claim.claimNumber,'CLAIM-123');assert.ok(!JSON.stringify(d).includes('inventory-comparisons/'));const s=state();s.contentsCare.items[0].description='Changed current inventory';m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);const after=await(await reconGet(comp.id)).json();assert.equal(after.detail.baseline.rows[1].label,'Refrigerator');assert.equal(after.detail.baseline.rows[1].rcvCents,29999);});
test('earlier exports reconstruct their baseline from the actual immutable Excel workbook',async()=>{const comp=await reconFixture(true),d=await(await reconGet(comp.id)).json();assert.equal(d.detail.baseline.rows[1].label,'Refrigerator');assert.equal(d.detail.baseline.rows[1].rcvCents,29999);assert.equal(d.detail.baseline.rows[0].rcvCents,null);assert.ok(d.detail.baseline.rows[1].links.some(l=>l.id==='source'));});
