test('reviewed comparison shows price and valuation differences without altering inventory, demand or payments',async()=>{let comp=await reconFixture();comp=await addCarrier(comp);const before=state();const r=await reconPost(groupInput(comp));assert.equal(r.status,200,await r.clone().text());const d=await(await reconGet(comp.id)).json(),g=d.detail.view.groups[0];assert.equal(g.adpaRCV,29999);assert.equal(g.carrierRCV,19999);assert.equal(g.gap,10000);assert.ok(g.flags.includes('Carrier extended RCV is lower'));assert.ok(g.flags.includes('Carrier unit replacement price is lower'));assert.equal(d.detail.view.byBasis.RCV.disputedGapCents,10000);assert.equal(d.detail.view.byBasis.ACV.disputedGapCents,null);assert.equal(g.adpaACV,null);assert.deepEqual(state().items,before.items);assert.deepEqual(state().buckets,before.buckets);assert.deepEqual(state().pricing,before.pricing);});
