test('duplicate grouping and incomplete source checks cannot double count a physical item',async()=>{let comp=await reconFixture();comp=await addCarrier(comp);assert.equal((await reconPost(groupInput(comp))).status,200);assert.equal((await reconPost(groupInput(comp))).status,400);assert.equal((await reconPost({...groupInput(comp,{adpaRefs:['item:0'],carrierIds:[]}),sourceChecked:false})).status,400);const view=await(await reconGet(comp.id)).json();assert.equal(view.detail.view.byBasis.RCV.disputedGapCents,10000);});
