test('edited carrier transcriptions invalidate earlier reviews and supplements; sources and removal histories are retained',async()=>{let comp=await reconFixture();comp=await addCarrier(comp);await reconPost(groupInput(comp));await excludeLegacy(comp);let d=await(await reconGet(comp.id)).json();assert.equal(d.detail.view.ready,true);assert.equal((await reconPost({action:'supplement',comparisonId:comp.id,body:d.detail.suggestedSupplement,reviewConfirmed:true})).status,200);d=await(await reconGet(comp.id)).json();const draft=d.detail.drafts[0];assert.equal(draft.current,true);const response=await reconApi.GET(new Request('https://claims.test'+draft.url));assert.equal(response.status,200);const text=await response.text();assert.ok(text.includes('Claim CLAIM-123'));assert.ok(text.includes('Difference $100.00'));assert.ok(text.includes('Carrier source: carrier CSV row 2'));const line=comp.carrierRows[0];const update=Object.fromEntries(['description','room','tag','quantity','unit','unitPrice','rcv','depreciation','acv','locator','quote'].map(k=>[k,line[k]]));update.rcv='219.99';update.acv='169.99';// A source-accurate correction requires an actual revised original.
 const bytes=new TextEncoder().encode('Refrigerator,Kitchen,1,EA,219.99,219.99,50.00,169.99');m.sqlite.prepare('INSERT INTO evidence VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('revision',id,companyModule.ADPA_OWNER,'Carrier revision.txt','text/plain',bytes.length,'Contents','','[]','revision-key','2026-10-14');await m.files().put('revision-key',bytes);update.quote=new TextDecoder().decode(bytes);update.locator='Line 1';assert.equal((await reconPost({action:'manual',comparisonId:comp.id,fileId:'revision',rowId:line.id,line:update,sourceChecked:true})).status,200);d=await(await reconGet(comp.id)).json();assert.equal(d.detail.view.groups.find(g=>g.disposition==='Disputed').stale,true);assert.equal(d.detail.view.byBasis.RCV.disputedGapCents,null);assert.equal(d.detail.drafts[0].current,false);assert.equal((await reconApi.GET(new Request('https://claims.test'+draft.url))).status,409);assert.ok(d.detail.history.some(h=>h.action==='carrier-row revision'));});
test('supplement requires all rows grouped and supported, and source changes or claim identity changes block its download',async()=>{let comp=await reconFixture();comp=await addCarrier(comp);await reconPost(groupInput(comp));assert.equal((await reconPost({action:'supplement',comparisonId:comp.id,body:'Unreviewed rows remain',reviewConfirmed:true})).status,400);await excludeLegacy(comp);let d=await(await reconGet(comp.id)).json();await reconPost({action:'supplement',comparisonId:comp.id,body:d.detail.suggestedSupplement,reviewConfirmed:true});d=await(await reconGet(comp.id)).json();const url=d.detail.drafts[0].url;m.sqlite.prepare("UPDATE claims SET name='Different insured' WHERE id=?").run(id);assert.equal((await reconApi.GET(new Request('https://claims.test'+url))).status,409);});
test('workbook parser supports stored and compressed OpenXML, shared strings and formulas are preserved as unsafe import fields',async()=>{await exportFixture();const model=inventory.exportModel({id,name:'Synthetic',address:'Address',version:1,state:state()},[file],'https://claims.test',new Date().toISOString()),bytes=xlsxLib.inventoryXlsx(model);const sheets=carrierSheet.readWorkbook(bytes);assert.equal(sheets.find(s=>s.name==='Inventory').rows[2].cells[5],'Refrigerator');assert.equal(sheets.find(s=>s.name==='Inventory').rows[2].cells[9],'299.99');const {zipSync,strToU8}=await import('fflate');const compressed=zipSync({'xl/workbook.xml':strToU8('<workbook xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Contents" r:id="rId1"/></sheets></workbook>'),'xl/_rels/workbook.xml.rels':strToU8('<Relationships><Relationship Id="rId1" Target="worksheets/sheet1.xml"/></Relationships>'),'xl/sharedStrings.xml':strToU8('<sst><si><t>Designer shoes</t></si></sst>'),'xl/worksheets/sheet1.xml':strToU8('<worksheet><sheetData><row r="2"><c r="A2" t="s"><v>0</v></c><c r="F2"><f>100+20</f><v>120</v></c></row></sheetData></worksheet>')});const parsed=carrierSheet.readWorkbook(compressed);assert.equal(parsed[0].rows[0].cells[0],'Designer shoes');assert.ok(parsed[0].rows[0].formulaColumns.includes(5));assert.throws(()=>reconLib.tableLines(parsed[0],2,2,{...emptyMap(),description:0,rcv:5}),/Formula/);});
function emptyMap(){return Object.fromEntries(reconLib.carrierFields.map(k=>[k,-1]));}
test('CSV keeps quoted commas/newlines and unknown amounts; malformed money, entities and oversized workbooks fail',async()=>{const table=carrierSheet.readDelimited('Description,RCV\r\n"Designer shoes, blue",1299.99\r\n"Second\nitem",\r\n')[0];assert.equal(table.rows[1].cells[0],'Designer shoes, blue');assert.equal(table.rows[2].cells[0],'Second\nitem');assert.equal(carrierSheet.moneyCents('$1,299.99'),129999);assert.equal(carrierSheet.moneyCents(''),null);assert.throws(()=>carrierSheet.moneyCents('1.234'),/USD/);assert.throws(()=>carrierSheet.moneyCents('-10'),/USD/);assert.throws(()=>carrierSheet.readWorkbook(new Uint8Array(8*1024*1024+1)),/8 MB/);const {zipSync,strToU8}=await import('fflate');const bad=zipSync({'xl/workbook.xml':strToU8('<!DOCTYPE foo [<!ENTITY x SYSTEM "file:///etc/passwd">]><workbook/>'),'xl/_rels/workbook.xml.rels':strToU8('<Relationships/>')});assert.throws(()=>carrierSheet.readWorkbook(bad),/entities/);});
test('RCV/ACV, packs, quantity and depreciation differences remain explicit and are never combined into one money total',()=>{const a={ref:'a',label:'Six-piece set',identity:'',tag:'',room:'Kitchen',quantity:'2',unit:'Set',rcvCents:30000,depreciationCents:5000,acvCents:25000,unitPriceCents:15000,status:'Approved proposal',flags:[],links:[]},file={id:'carrier',filename:'Carrier.pdf',mime:'application/pdf',size:5,created:'2026-01-01'},b={sourceFiles:[],rows:[a]},comp={baselineDigest:'fixed',carrierRows:[{id:'c',fileId:'carrier',description:'Six pieces',quantity:'6',unit:'EA',unitPriceCents:2500,rcvCents:15000,depreciationCents:7500,acvCents:7500,flags:[],proof:{metadata:contact.fileMetadata(file)}}],groups:[]};const g={id:'g',adpaRefs:['a'],carrierIds:['c'],basis:'RCV',disposition:'Disputed',note:'Reviewed packs/sets: these are different counts, gap needs resolution',agreement:null};g.snapshot=reconLib.groupSnapshot(g,b,comp);comp.groups=[g];let v=reconLib.reconciliationView(comp,b,[file]);assert.ok(v.groups[0].flags.includes('Quantity / unit differs'));assert.ok(v.groups[0].flags.includes('Depreciation differs'));assert.ok(!v.groups[0].flags.includes('Carrier unit replacement price is lower'));assert.equal(v.byBasis.RCV.disputedGapCents,15000);assert.equal(v.byBasis.ACV.disputedGapCents,null);});
