const eventBody=(c,stage,patch={})=>({action:'stage',checkId:c.id,stage,date:'2026-10-02',fileId:'source',locator:'Reviewed carrier issuance / possession / bank record',basis:'Synthetic original supports this specific status; no inference from endorsement',sourceChecked:true,...patch});
test('check leads preserve whole-check facts and suggest memo buckets without posting or silently selecting allocations',async()=>{const c=await payFixture(),d=await(await payGet()).json();assert.equal(d.checks[0].current,false);assert.equal(state().payments.length,0);assert.equal(d.checks[0].facts.amountWords,'One thousand dollars');assert.equal(d.checks[0].facts.payees,checkData.payees);assert.ok(d.checks[0].suggestions.some(s=>s.category==='Pack-out'));assert.equal(d.checks[0].review,undefined);assert.equal(d.checks[0].claimCandidates[0].id,id);assert.equal(d.aiConnected,false);assert.equal(d.bankConnected,false);assert.ok(!JSON.stringify(d).includes('private-key'));});
test('reviewed split allocations feed a single existing ledger row; stages are separate amounts and do not change bucket totals',async()=>{const before=structuredClone(original),c=await approvedCheck();let s=state();assert.equal(s.payments.length,1);assert.equal(s.payments[0].managedCheckId,c.id);assert.equal(s.payments[0].allocations[0].issued,null);assert.equal((await payPost(eventBody(c,'Issued'))).status,200);assert.equal((await payPost(eventBody(c,'Received',{date:'2026-10-03'}))).status,200);assert.equal((await payPost(eventBody(c,'Deposited',{date:'2026-10-04',fileId:'bank-confirmation'}))).status,200);assert.equal((await payPost(eventBody(c,'Released',{date:'2026-10-05',fileId:'bank-confirmation'}))).status,200);const d=await(await payGet()).json();assert.equal(d.buckets[1].issued,100000);assert.equal(d.buckets[1].received,100000);assert.equal(d.buckets[1].deposited,100000);assert.equal(d.buckets[1].released,100000);assert.equal(state().payments.length,1);assert.equal(state().payments[0].allocations[1].received,250);assert.equal(state().buckets[1].received,200);assert.deepEqual(state().items,before.items);assert.equal(state().payments[0].destinationAccount,'Lender-held claim proceeds — label only');});
test('approval requires exact positive split, source/identity/amount/duplicate checks and an existing bucket',async()=>{const c=await payFixture();assert.equal((await payPost({...allocationBody(c),amountWordsChecked:false})).status,400);assert.equal((await payPost(allocationBody(c,{allocations:[{coverage:1,category:'Property replacement',purpose:'ACV',amount:'999.99'}]}))).status,400);assert.equal((await payPost(allocationBody(c,{allocations:[{coverage:9,category:'Property replacement',purpose:'ACV',amount:'1000'}]}))).status,400);assert.equal((await payPost(allocationBody(c,{facts:{...checkData,printedClaimNumber:'FOREIGN-999'}}))).status,400);assert.equal(state().payments.length,0);});
test('same issuer/check number cannot be posted twice within or across claims, even from different pictures',async()=>{const c=await approvedCheck();const r=await payPost({action:'candidate',fileIds:['source'],locator:'Another picture of same check',facts:{...checkData,checkNumber:'123'},sourceChecked:true});assert.equal(r.status,200);const duplicate=state().paymentReview.checks.at(-1);assert.equal((await payPost(allocationBody(duplicate,{facts:{...checkData,checkNumber:'123'}}))).status,400);const otherId='22222222-2222-4222-8222-222222222222',s=structuredClone(state());m.sqlite.prepare('INSERT INTO claims VALUES (?,?,?,?,?,1,?,?)').run(otherId,companyModule.ADPA_OWNER,'Other claim','Other address',JSON.stringify(s),'2026-01-01','2026-01-01');const current=state();current.paymentReview.checks=current.paymentReview.checks.filter(ch=>ch.id!==c.id);current.payments=[];m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(current),id);assert.equal((await payPost(allocationBody(duplicate,{facts:{...checkData,checkNumber:'123'}}))).status,400);assert.equal(state().payments.length,0);});
test('status progression is source-based and chronological; a check image or endorsement cannot auto-mark received/deposited',async()=>{const c=await approvedCheck();assert.equal((await payPost(eventBody(c,'Deposited'))).status,400);assert.equal((await payPost(eventBody(c,'Received'))).status,400);assert.equal((await payPost({...eventBody(c,'Issued'),sourceChecked:false})).status,400);assert.equal((await payPost(eventBody(c,'Issued',{date:'2099-01-01'}))).status,400);assert.equal((await payPost(eventBody(c,'Issued'))).status,200);assert.equal((await payPost(eventBody(c,'Received',{date:'2026-09-30'}))).status,400);assert.equal(state().paymentReview.checks[0].stages.length,1);});
test('legacy payments are explicitly migrated rather than duplicated, preserving reviewed issued/received stages and history',async()=>{const c=await payFixture();const s=state();s.payments=[{id:'legacy1',reference:'Check 123',payee:'Synthetic Insured',issuedDate:'2026-10-02',receivedDate:'2026-10-03',evidenceId:'source',source:'Reviewed legacy source',allocations:[{coverage:1,category:'Property replacement',issued:1000,received:1000}],history:[]}];m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);assert.equal((await payPost(allocationBody(c))).status,400);assert.equal((await payPost(allocationBody(c,{legacyPaymentId:'legacy1',legacyLinkBasis:'Verified same physical check and existing complete stages',legacyStagesChecked:true}))).status,200);const saved=state();assert.equal(saved.payments.length,1);assert.equal(saved.payments[0].id,'legacy1');assert.equal(saved.payments[0].allocations.reduce((n,a)=>n+a.received,0),1000);assert.ok(saved.payments[0].history[0].allocations);assert.equal((await(await payGet()).json()).buckets[1].received,100000);});
test('ambiguous partial legacy receipt cannot be inflated to a whole received check during migration',async()=>{const c=await payFixture();const s=state();s.payments=[{id:'partial',reference:'123',issuedDate:'2026-10-02',receivedDate:'2026-10-03',evidenceId:'source',allocations:[{coverage:1,issued:1000,received:400}]}];m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);assert.equal((await payPost(allocationBody(c,{legacyPaymentId:'partial',legacyLinkBasis:'Check identity needs reconciliation',legacyStagesChecked:true}))).status,400);assert.equal(state().payments[0].allocations[0].received,400);});
test('carrier statement compares only explicit net payable to matched issued checks; prior payments are not added or deducted again',async()=>{const c=await approvedCheck();await payPost(eventBody(c,'Issued'));const body={action:'statement',statementId:'',reference:'Advice 1',coverage:1,scope:'Single payment advice',asOf:'2026-10-01',rcv:'5000',acv:'4000',recoverable:'1000',nonrecoverable:'',deductible:'500',priorPayments:'2500',payable:'1000',checkIds:[c.id],noneIssuedConfirmed:false,fileId:'source',locator:'Statement current payment line',basis:'Checked net current advice; previous payments are explanatory, not another check',sourceChecked:true};assert.equal((await payPost(body)).status,200);const d=await(await payGet()).json();assert.equal(d.statements[0].linkedIssuedCents,100000);assert.equal(d.statements[0].differenceCents,0);assert.equal(d.statements[0].priorPayments,'2500');assert.equal(d.buckets[1].issued,100000);assert.equal((await payPost(body)).status,400);});
test('unknown and explicitly confirmed no issued checks are distinct reconciliation states',async()=>{await payFixture();const b={action:'statement',statementId:'',reference:'Advice unknown',coverage:1,scope:'Single payment advice',asOf:'2026-10-01',rcv:'',acv:'',recoverable:'',nonrecoverable:'',deductible:'',priorPayments:'',payable:'1000',checkIds:[],noneIssuedConfirmed:false,fileId:'source',locator:'Advice',basis:'Source reviewed; matching issuance not established',sourceChecked:true};await payPost(b);let d=await(await payGet()).json();assert.equal(d.statements[0].linkedIssuedCents,null);assert.equal(d.statements[0].differenceCents,null);await payPost({...b,statementId:d.statements[0].id,noneIssuedConfirmed:true,basis:'Reviewed issuance records; explicitly no relevant issued checks'});d=await(await payGet()).json();assert.equal(d.statements[0].linkedIssuedCents,0);assert.equal(d.statements[0].differenceCents,100000);});
test('potential depreciation requires policy and carrier source review and only explicit depreciation allocations count as release',async()=>{const c=await approvedCheck({allocations:[{coverage:1,category:'Property replacement',purpose:'Recoverable depreciation',amount:'500'},{coverage:1,category:'Property replacement',purpose:'ACV',amount:'500'}]});await payPost(eventBody(c,'Issued'));const bytes=new TextEncoder().encode('%PDF-policy');m.sqlite.prepare('INSERT INTO evidence VALUES (?,?,?,?,?,?,?,?,?,?,?)').run('deppolicy',id,companyModule.ADPA_OWNER,'Policy.pdf','application/pdf',bytes.length,'Policy','','[]','deppolicy-key','2026-01-01');await m.files().put('deppolicy-key',bytes);const body={action:'depreciation',recordId:'',coverage:1,recoverable:'2000',releasedCheckIds:[c.id],noneReleasedConfirmed:false,status:'Proof submitted',conditions:'Checked replacement and proof-of-purchase conditions; carrier review still pending',nextAction:'Confirm acceptance of receipts and remaining recoverability',followUp:'2026-10-14',policyFileId:'deppolicy',policyLocator:'Policy page 2 loss settlement',fileId:'source',locator:'Carrier withholding statement',sourceChecked:true,policyChecked:true};assert.equal((await payPost(body)).status,200);const d=await(await payGet()).json();assert.equal(d.depreciation[0].releasedIssuedCents,50000);assert.equal(d.depreciation[0].unreleasedCents,150000);assert.equal(d.depreciation[0].recoverableCents,200000);assert.equal(state().buckets[1].received,200);assert.equal((await payPost(body)).status,400);});
test('changed bucket identities or source bytes block allocation/status reviews; managed ledger records cannot be forged through ordinary writes',async()=>{const c=await approvedCheck(),before=state();assert.match(authority.ordinaryWriteError({}, {paymentReview:{checks:[{}]}}),/Payment review/);const next=structuredClone(before);next.payments[0].allocations[0].received=999;assert.match(authority.ordinaryWriteError(before,next),/Managed check/);assert.equal(authority.ordinaryWriteError(before,before),null);const s=state();s.buckets[1].name='Different bucket';m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);assert.equal((await(await payGet()).json()).checks[0].current,false);assert.equal((await payPost(eventBody(c,'Issued'))).status,400);await m.files().put('private-key',new Uint8Array([5,4,3,2,1]));assert.equal((await payPost(allocationBody(c))).status,400);});
test('void/reissued records leave active totals without pretending to stop a bank check; prior stages remain historical',async()=>{const c=await approvedCheck();await payPost(eventBody(c,'Issued'));await payPost(eventBody(c,'Received',{date:'2026-10-03'}));assert.equal((await payPost({action:'void',checkId:c.id,reason:'Carrier source confirms stopped check/reissue; record update only',fileId:'source',locator:'Carrier correspondence',sourceChecked:true})).status,200);const d=await(await payGet()).json();assert.equal(d.buckets[1].received,null);assert.ok(d.checks[0].voided);assert.equal(state().payments[0].voided,true);assert.equal(state().paymentReview.checks[0].stages.length,2);assert.equal(state().buckets[1].received,200);});
test('AI full-check extraction reads numeric/written amounts and all payees, never authorizes allocation or banking and rejects multiple physical checks',async()=>{let request,multiple=false;const selected=[{id:'front',filename:'Full front.jpg',mime:'image/jpeg',size:5},{id:'back',filename:'Full back.jpg',mime:'image/jpeg',size:5}],fetcher=async(url,options)=>{request=JSON.parse(options.body);return Response.json({status:'completed',output:[{content:[{type:'output_text',text:JSON.stringify({differentChecks:multiple,facts:checkData})}]}]});};const f=await checkAI.extractCheck('test','test-model',selected,async()=>new Uint8Array(5).buffer,fetcher);assert.equal(f.amountWords,'One thousand dollars');assert.equal(f.payees,checkData.payees);assert.equal(request.tools,undefined);assert.equal(request.store,false);assert.ok(request.instructions.includes('ENTIRE'));assert.ok(request.instructions.includes('MICR'));assert.equal(f.allocations,undefined);multiple=true;await assert.rejects(checkAI.extractCheck('test','test-model',selected,async()=>new Uint8Array(5).buffer,fetcher),/Multiple physical/);});
test('payment endpoints enforce ownership, strict review/version/origin checks and honest missing AI activation',async()=>{const c=await payFixture();assert.equal((await payPost({action:'extract',fileIds:['source']})).status,503);assert.equal((await payPost({...allocationBody(c),version:999})).status,409);assert.equal((await paymentApi.POST(new Request('https://claims.test/api/payment-review?id='+id,{method:'POST',headers:{origin:'https://evil.test'},body:'{}'}))).status,403);m.setUser({userId:'other',email:'other@example.test'});assert.equal((await payGet()).status,404);m.setUser(null);assert.equal((await payGet()).status,401);});
test('new unlinked issued depreciation checks prevent treating an old no-payment confirmation as a current remaining balance',async()=>{const c=await approvedCheck({allocations:[{coverage:1,category:'Property replacement',purpose:'Recoverable depreciation',amount:'1000'}]});await payPost(eventBody(c,'Issued'));const s=state();s.paymentReview.depreciation=[{id:'d1',coverage:1,bucketName:'Personal contents',recoverable:'2000',releasedCheckIds:[],noneReleasedConfirmed:true,status:'Proof submitted',conditions:'Source checked',nextAction:'Review release',followUp:'2026-10-14',proof:s.paymentReview.checks[0].sources[0],policyProof:s.paymentReview.checks[0].sources[0]}];m.sqlite.prepare('UPDATE claims SET state=? WHERE id=?').run(JSON.stringify(s),id);const d=await(await payGet()).json();assert.equal(d.depreciation[0].held,true);assert.equal(d.depreciation[0].unreleasedCents,null);assert.ok(d.depreciation[0].warnings.length);});
test('managed check receipt and lender-held release become morning actions; destination fields reject full account-number strings',async()=>{const c=await approvedCheck();await payPost(eventBody(c,'Issued'));await payPost(eventBody(c,'Received',{date:'2026-10-03'}));const s=state(),actions=morningLib.claimMorning({id,name:'Synthetic',address:'Address',state:s},[{...file,filename:'Photo.jpg'}],'2026-10-13').actions;assert.ok(actions.some(a=>a.title.includes('Review check')));assert.equal((await payPost(allocationBody(c,{destinationAccount:'Bank account 1234567890',legacyPaymentId:c.paymentId}))).status,400);});
test('bank deposit and fund release require a separate confirmation original; a check photo cannot serve as bank evidence',async()=>{const c=await approvedCheck();await payPost(eventBody(c,'Issued'));await payPost(eventBody(c,'Received',{date:'2026-10-03'}));assert.equal((await payPost(eventBody(c,'Deposited',{date:'2026-10-04'}))).status,400);assert.equal((await payPost(eventBody(c,'Deposited',{date:'2026-10-04',fileId:'bank-confirmation'}))).status,200);assert.equal((await payPost(eventBody(c,'Released',{date:'2026-10-05'}))).status,400);});

test('source metadata changes invalidate pricing triage and reject its opened source key',async()=>{await save();const oldKey=lib.pricingSourceKey(file);m.sqlite.prepare('UPDATE evidence SET filename=? WHERE id=?').run('Changed photo.jpg','source');const d=await(await get()).json();assert.equal(d.queue[0].status,'Not reviewed');assert.equal(d.candidates[0].reviewed,false);assert.equal((await api.POST(request({action:'triage',version:3,fileId:'source',sourceKey:oldKey,disposition:'Reviewed for pricing',note:'Old photo review'}))).status,409);assert.deepEqual(state().items,original.items);});
test('candidate review key protects against old confirmation after a valid claim refresh',async()=>{await save();const oldKey=(await(await get()).json()).candidates[0].reviewKey,s=state();s.pricing.candidates[0].identity='Changed specifications';m.sqlite.prepare('UPDATE claims SET state=?,version=version+1 WHERE id=?').run(JSON.stringify(s),id);assert.equal((await api.POST(request({action:'review',version:latestVersion(),candidateId:c.id,reviewKey:oldKey,note:'Older comparison',sourceChecked:true}))).status,409);assert.equal(state().pricing.reviews.c1,undefined);});
test('same target with different physical keys still blocks duplicate pricing and invalid totals stay incomplete',()=>{const s={...original,pricing:{candidates:[c,{...c,id:'other',physicalKey:'another-key'}],triage:{source:{sourceKey:lib.pricingSourceKey(file),disposition:'Reviewed for pricing'}}}};assert.ok(lib.candidateGaps(c,[file],s).some(x=>x.includes('same destination record')));s.pricing.candidates=[{...c,quantity:'10000000000000000000000000'}];assert.equal(lib.pricingView(s,[file]).candidates[0].alternatives[0].total,null);assert.equal(lib.validPricingTime('2026-02-30T12:00:00Z'),false);assert.equal(lib.validPricingTime('2026-02-28T12:00:00-08:00'),true);});
test('source metadata changing during approval prevents committing a proposal',async()=>{const candidate=await reviewedReplacement();m.storage.set('private-key',{async arrayBuffer(){m.sqlite.prepare('UPDATE evidence SET category=? WHERE id=?').run('Changed source category','source');return new Uint8Array(5).buffer;}});assert.equal((await approve(candidate)).status,409);assert.equal(state().pricing.replacementApprovals,undefined);});

test('malformed pricing quantities stay incomplete while supported fractional work quantities calculate',()=>{for(const quantity of ['1e2',' 2 ','0x10','1.00001','-2','0']){const s={...original,pricing:{candidates:[{...c,quantity}]}};assert.equal(lib.pricingView(s,[file]).candidates[0].alternatives[0].total,null,quantity);assert.ok(lib.candidateGaps({...c,quantity},[file],s).includes('Enter a supported positive quantity.'));}const s={...original,pricing:{candidates:[{...c,quantity:'1.5'}]}};assert.equal(lib.pricingView(s,[file]).candidates[0].alternatives[0].total,16075);});
